    var items=null,selected=value;
    if(/酒店组织编号|酒店组织|充值酒店/.test(label)){items=identity.orgs.filter(function(o){return o.type==='hotel';});label='酒店';}
    else if(/工厂组织编号|承接洗涤厂组织编号/.test(label)){items=identity.orgs.filter(function(o){return o.type==='factory';});label='洗涤厂';}
