  function rechargeLabel(status){return {PENDING:'待审批',DIRECT:'直接入账',APPROVED:'已通过 · 已入账',REJECTED:'已驳回'}[status]||'历史记录（无审批信息）';}
  function rechargeBadge(status){return badge(rechargeLabel(status),status==='APPROVED'?'success':status==='REJECTED'?'danger':status==='PENDING'?'warning':'');}
