  function flowTerminalTotals(hotel,kind){flowSetup();var title=kind==='in'?'酒店累计入库':'酒店累计出库';if(!hotel)return panel(title,'','<p class="identity-empty">'+(kind==='in'?'选择酒店或退污申请后查看累计入库':'选择本站备货订单后查看酒店累计出库')+'</p>');var skus=syncTerminalSkus().slice();catalog.orders.filter(function(o){return o.hotel===hotel&&o.factory==='org-factory-1';}).forEach(function(o){linenLines(o).forEach(function(l){if(!skus.some(function(s){return s.id===l.sku;}))skus.push({id:l.sku,name:l.name});});});return panel(title,esc((identityOrg(hotel)||{}).name),managementTable(kind==='in'?['布草','日常入库','退污入库','累计入库']:['布草','累计出库'],skus.map(function(s){if(kind==='in'){var rows=syncData.receipts.filter(function(r){return r.hotel===hotel&&r.sku===s.id&&r.factory==='org-factory-1';}),daily=rows.filter(function(r){return r.type==='DAILY';}).reduce(function(n,r){return n+r.quantity;},0),refund=rows.filter(function(r){return r.type==='RETURN';}).reduce(function(n,r){return n+r.quantity;},0);return[esc(s.name),daily,refund,daily+refund];}var out=catalog.orders.filter(function(o){return o.hotel===hotel&&o.factory==='org-factory-1';}).reduce(function(n,o){return n+linenLines(o).filter(function(l){return l.sku===s.id;}).reduce(function(v,l){return v+Number((o.stocked||{})[l.name]||0);},0);},0);return[esc(s.name),out];})));}
